using sv_f9fd9f8dc531441b98300047231eaa8b.Models;

namespace sv_f9fd9f8dc531441b98300047231eaa8b.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_f9fd9f8dc531441b98300047231eaa8b.Models;

namespace sv_f9fd9f8dc531441b98300047231eaa8b.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with San Marzano tomatoes, fresh mozzarella, and basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy Roman pasta with guanciale, pecorino, egg yolks, and black pepper.", 25),
            new(3, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked slowly in broth with Parmigiano-Reggiano.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Marinated chicken pieces in a rich, spiced tomato-cream sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach purée with cubes of paneer cheese and aromatic spices.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with spiced meat, fried onions, and saffron.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Spit-grilled pork with pineapple, cilantro, and onion on corn tortillas.", 40),
            new(8, "Guacamole", "Ripe avocados mashed with lime juice, cilantro, jalapeño, and tomato.", 10),
            new(9, "Churros", "Fried dough pastries coated in cinnamon sugar, served with chocolate sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

